//! Exact elements of a multiquadratic field, `Q(sqrt k1, ..., sqrt kt)`.
//!
//! Two jobs live here. The expression fold reads a closed tree of rational
//! arithmetic over square roots — the quotient chains a Gauss-Jordan
//! elimination over radicals produces, which no evaluator can fold — and
//! reduces it to one exact, readable element. And the type itself is a
//! public exact number: an element of the field generated by up to eight
//! squarefree radicands, closed under `+ - * /` with no loss of exactness.
//!
//! Storage is sparse: only the monomials whose coefficient differs from zero
//! are kept, as ascending `(mask, coefficient)` pairs. A typical element
//! holds a handful of monomials out of the `2^t` the basis spans, so the
//! dense renderings waste nearly all their coefficients; elements allocate
//! proportional to what they actually carry, and multiplication costs a
//! product of the term counts rather than of the field's size. Transient
//! dense accumulators appear inside single operations, never in storage.
//!
//! Unlike [`Multiquadratic`] nothing here is const-generic, so types linking
//! this crate from another crate or binary monomorphize it freely.
//!
//! [`Multiquadratic`]: crate::math::algebra::algebraic::Multiquadratic

use super::rational::Rat;
use super::surd::{self};

/// How many independent radicands an element may combine.
///
/// The limit bounds the dense accumulators inside a single operation
/// (`2^count` coefficients, transitory) and keeps rendered elements
/// readable: entries beyond a handful of distinct radicals would print as
/// unreadable radical sums anyway. Stored elements hold only their nonzero
/// monomials, so the limit costs nothing between operations.
pub const MAX_RADICANDS: usize = 8;

/// An exact element of a multiquadratic field: a rational coefficient for
/// each basis monomial it carries, keyed by the bitmask of the radicands
/// the monomial multiplies.
///
/// The element is zero exactly when it holds no monomials; a zero
/// coefficient is never stored. # Examples
///
/// ```
/// use symrust::math::algebra::field::FieldElement;
/// use symrust::math::algebra::rational::Rat;
///
/// // 1 / 5 is sqrt(5) / 5 as a field element: exact, one radical.
/// let element = FieldElement::sqrt_rational(Rat::new(1, 5).unwrap()).unwrap();
/// assert!((element.to_f64() - (5.0f64).sqrt() / 5.0).abs() < 1e-12);
/// ```
#[derive(Clone, Debug, Default)]
pub struct FieldElement {
    /// The squarefree radicands, sorted ascending. This is the field's
    /// basis: monomial mask bit `i` multiplies `sqrt(radicands[i])`.
    radicands: Vec<i64>,
    /// The held monomials, `(mask, coefficient)` with masks strictly
    /// ascending and no zero coefficient. Zero is an empty vector.
    terms: Vec<(usize, Rat)>,
}

impl FieldElement {
    /// The rational value `q`.
    #[must_use]
    pub fn from_rat(value: Rat) -> Self {
        Self::zero_with_radicands(Vec::new()).with_term(0, value)
    }

    /// `sqrt(k)` for a positive integer `k`, trimmed to its squarefree
    /// part: `sqrt(12)` is `2 sqrt(3)`. `None` when the trim leaves nothing
    /// radical — a perfect square is rational, not a field radical.
    pub fn sqrt_of(k: i64) -> Option<Self> {
        if k <= 0 {
            return None;
        }
        let (squarefree, rest) = surd::squarefree_part(i128::from(k))?;
        if squarefree <= 1 {
            return None;
        }
        let rest = Rat::from_i64(i64::try_from(rest).ok()?);
        Some(Self::zero_with_radicands(vec![squarefree]).with_term(1, rest))
    }

    /// `sqrt(q)` for a rational `q`: exact when `q` is a rational square,
    /// otherwise a single radical, via `sqrt(n / d) = sqrt(n d) / d` — so
    /// `1 / 5` is `sqrt(5) / 5`. `None` for a negative `q`.
    pub fn sqrt_rational(value: Rat) -> Option<Self> {
        if let Some(root) = value.sqrt_exact() {
            return Some(Self::from_rat(root));
        }
        if value.is_negative() {
            return None;
        }
        let (numerator, denominator) = value.parts();
        let radicand = numerator.checked_mul(denominator)?;
        let (squarefree, rest) = surd::squarefree_part(radicand)?;
        if squarefree <= 1 {
            return None;
        }
        Self::sqrt_of(squarefree)?.scale(Rat::new(rest, denominator)?)
    }

    /// Whether the element is zero. Stored elements carry no zero terms, so
    /// this is a bare emptiness check.
    #[must_use]
    pub fn is_zero(&self) -> bool {
        self.terms.is_empty()
    }

    /// Whether the element carries no radical part.
    #[must_use]
    pub fn is_rational(&self) -> bool {
        self.radicands.is_empty() || self.terms.iter().all(|(mask, _)| *mask == 0)
    }

    /// The rational constant term. The whole value only when
    /// [`is_rational`](Self::is_rational) holds.
    #[must_use]
    pub fn rational_part(&self) -> Rat {
        self.terms
            .first()
            .filter(|(mask, _)| *mask == 0)
            .map_or(Rat::ZERO, |(_, coefficient)| *coefficient)
    }

    /// The squarefree radical basis this element is expressed over, sorted
    /// ascending: monomial mask bit `i` multiplies `sqrt(radicands()[i])`.
    #[must_use]
    pub fn radicands(&self) -> &[i64] {
        &self.radicands
    }

    /// The held monomials, `(mask, coefficient)` with masks ascending and no
    /// zero coefficient. The empty element is zero.
    #[must_use]
    pub fn terms(&self) -> &[(usize, Rat)] {
        &self.terms
    }

    /// The approximate value: each coefficient times the square roots of
    /// its monomial's radicands.
    #[must_use]
    pub fn to_f64(&self) -> f64 {
        let mut total = 0.0;
        for (mask, coefficient) in &self.terms {
            let mut factor = 1.0;
            for (bit, radicand) in self.radicands.iter().enumerate() {
                if mask & (1 << bit) != 0 {
                    factor *= (*radicand as f64).sqrt();
                }
            }
            total += coefficient.to_f64() * factor;
        }
        total
    }

    /// Add, over the merged radicand basis. `None` when the merged field
    /// would exceed [`MAX_RADICANDS`] radicands or a coefficient overflows.
    pub fn add(&self, other: &Self) -> Option<Self> {
        let radicands = combined_radicands(&self.radicands, &other.radicands)?;
        let left = self.remap(&radicands)?;
        let right = other.remap(&radicands)?;
        let mut terms = left;
        terms.extend(right);
        Some(Self::canonical(radicands, terms))
    }

    /// Subtract, through [`add`](Self::add) of the negation.
    pub fn sub(&self, other: &Self) -> Option<Self> {
        self.add(&other.neg())
    }

    /// Multiply by expanding each pair of held monomials: the shared
    /// radicands contribute their product as a rational factor, and the
    /// symmetric difference becomes the result's radical part. The cost is
    /// quadratic in the terms actually held, not in the field's size.
    pub fn mul(&self, other: &Self) -> Option<Self> {
        let radicands = combined_radicands(&self.radicands, &other.radicands)?;
        let left = self.remap(&radicands)?;
        let right = other.remap(&radicands)?;
        let patterns = 1usize << radicands.len();
        // A transient dense accumulator: at most `MAX_RADICANDS` bits, so at
        // most 256 slots, discarded as soon as the product is canonicalised.
        let mut dense = vec![Rat::ZERO; patterns];
        for (left_mask, left_coefficient) in &left {
            for (right_mask, right_coefficient) in &right {
                let mut shared_rational = Rat::ONE;
                for (bit, radicand) in radicands.iter().enumerate() {
                    if left_mask & right_mask & (1 << bit) != 0 {
                        shared_rational = shared_rational.mul(Rat::from_i64(*radicand))?;
                    }
                }
                let target = left_mask ^ right_mask;
                let term = left_coefficient
                    .mul(*right_coefficient)?
                    .mul(shared_rational)?;
                dense[target] = dense[target].add(term)?;
            }
        }
        Some(Self::canonical(
            radicands,
            dense.into_iter().enumerate().collect(),
        ))
    }

    /// Divide, multiplying by the [`recip`](Self::recip)rocal. `None` when
    /// `other` is zero, or when either side leaves the field.
    pub fn div(&self, other: &Self) -> Option<Self> {
        self.mul(&other.recip()?)
    }

    /// Scale every coefficient by a rational factor.
    pub fn scale(&self, factor: Rat) -> Option<Self> {
        let mut terms = Vec::with_capacity(self.terms.len());
        for (mask, coefficient) in &self.terms {
            terms.push((*mask, coefficient.mul(factor)?));
        }
        Some(Self::canonical(self.radicands.clone(), terms))
    }

    /// Negate every coefficient.
    #[must_use]
    pub fn neg(&self) -> Self {
        let terms = self
            .terms
            .iter()
            .map(|(mask, coefficient)| (*mask, coefficient.neg()))
            .collect();
        Self {
            radicands: self.radicands.clone(),
            terms,
        }
    }

    /// Multiplicative inverse: the field is a tower of quadratic extensions,
    /// so the product of all `2^t` conjugates is the rational norm and the
    /// inverse is the product of every conjugate but this one, over it.
    /// `None` for zero or a zero norm.
    pub fn recip(&self) -> Option<Self> {
        let patterns = 1usize << self.radicands.len();
        let mut norm_product = Self::from_rat(Rat::ONE);
        for pattern in 0..patterns {
            norm_product = norm_product.mul(&self.conjugate(pattern))?;
        }
        let norm = norm_product.rational_part();
        if norm.is_zero() {
            return None;
        }
        let mut inverse = Self::from_rat(Rat::ONE);
        for pattern in 1..patterns {
            inverse = inverse.mul(&self.conjugate(pattern))?;
        }
        inverse.scale(norm.recip()?)
    }

    /// The conjugate negating the monomials that include the radicands of
    /// every set bit of `pattern`. Each pattern bit flips its own factor, so
    /// a monomial containing two flipped radicands — `sqrt(3) sqrt(5)` under
    /// both flips — comes back positive: the sign is the parity of the bits
    /// the monomial shares with the pattern.
    fn conjugate(&self, pattern: usize) -> Self {
        let terms = self
            .terms
            .iter()
            .map(|(mask, coefficient)| {
                if (mask & pattern).count_ones() % 2 == 1 {
                    (*mask, coefficient.neg())
                } else {
                    (*mask, *coefficient)
                }
            })
            .collect();
        Self {
            radicands: self.radicands.clone(),
            terms,
        }
    }

    /// Re-express this element over an expanded radicand list: each held
    /// monomial's radicands map to the subsets of the target list carrying
    /// the same squarefree parts. Radicands reached twice along the way are
    /// squared there — a rational factor, not a radical one. The result is
    /// sparse and mask-ascending over the target basis.
    fn remap(&self, target: &[i64]) -> Option<Vec<(usize, Rat)>> {
        let mut dense = vec![Rat::ZERO; 1usize << target.len()];
        for (source_mask, coefficient) in &self.terms {
            let mut target_mask = 0usize;
            // How often each target radicand enters the decomposition: a
            // radicand reached twice is squared — its square is rational.
            let mut appearances = vec![0u32; target.len()];
            let mut rational = Rat::ONE;
            for (bit, radicand) in self.radicands.iter().enumerate() {
                if source_mask & (1 << bit) == 0 {
                    continue;
                }
                let (mask, factor) = decompose_radicand(target, *radicand)?;
                rational = rational.mul(factor)?;
                target_mask ^= mask;
                for (target_bit, _) in target.iter().enumerate() {
                    if mask & (1 << target_bit) != 0 {
                        appearances[target_bit] += 1;
                    }
                }
            }
            // Each radicand appearing twice in the monomial contributes its
            // square as a rational factor; odd appearances keep the radical.
            for (target_bit, target_radicand) in target.iter().enumerate() {
                for _ in 0..appearances[target_bit] / 2 {
                    rational = rational.mul(Rat::from_i64(*target_radicand))?;
                }
            }
            let scaled = coefficient.mul(rational)?;
            dense[target_mask] = dense[target_mask].add(scaled)?;
        }
        Some(
            dense
                .into_iter()
                .enumerate()
                .filter(|(_, coefficient)| !coefficient.is_zero())
                .collect(),
        )
    }

    /// Render the element as an expression: one term per held monomial,
    /// joined by the coefficients' signs. A monomial whose radicands
    /// multiply to a squarefree product collapses into a single square root
    /// (`sqrt(5) sqrt(3)` reads `sqrt(15)`); radicands sharing a factor keep
    /// the collected form `3 sqrt(5)`. Positive terms come first (added),
    /// negative ones last (subtracted), so the rendering never shows a
    /// leading minus or a `+ -` join.
    #[must_use]
    pub fn to_node<T: crate::math::numeric::SymbolicLeaf>(
        &self,
    ) -> crate::math::structs::expr::node::Node<T> {
        use crate::math::structs::expr::node::Node;

        if self.is_zero() {
            return Node::zero();
        }
        let mut result: Option<Node<T>> = None;
        for (mask, coefficient) in &self.terms {
            if coefficient.is_negative() {
                continue;
            }
            let Some((extra, root)) = radical_part::<T>(&self.radicands, *mask) else {
                continue;
            };
            let Some(effective) = coefficient.mul(extra) else {
                continue;
            };
            if effective.is_zero() {
                continue;
            }
            let term = match &root {
                Some(root) => Node::multiply_by_rational(root.clone(), effective),
                None => effective.to_node(),
            };
            result = Some(match result {
                None => term,
                Some(accumulator) => Node::add(accumulator, term),
            });
        }
        for (mask, coefficient) in &self.terms {
            if !coefficient.is_negative() {
                continue;
            }
            let Some((extra, root)) = radical_part::<T>(&self.radicands, *mask) else {
                continue;
            };
            let Some(magnitude) = coefficient.neg().mul(extra) else {
                continue;
            };
            if magnitude.is_zero() {
                continue;
            }
            let term = match &root {
                Some(root) => Node::multiply_by_rational(root.clone(), magnitude),
                None => magnitude.to_node(),
            };
            result = Some(match result {
                None => {
                    // The first term keeps its negative sign inside itself.
                    match (&root, coefficient.mul(extra)) {
                        (Some(root), Some(signed)) => {
                            Node::multiply_by_rational(root.clone(), signed)
                        }
                        (None, Some(signed)) => signed.to_node(),
                        (_, None) => break,
                    }
                }
                Some(accumulator) => Node::sub(accumulator, term),
            });
        }
        result.unwrap_or_else(Node::zero)
    }

    /// An element with no terms over the given radicand basis.
    fn zero_with_radicands(radicands: Vec<i64>) -> Self {
        Self {
            radicands,
            terms: Vec::new(),
        }
    }

    /// This element with one more monomial, inserted in mask order. A zero
    /// coefficient adds nothing; the caller must not repeat a mask.
    fn with_term(mut self, mask: usize, coefficient: Rat) -> Self {
        if coefficient.is_zero() {
            return self;
        }
        let position = self
            .terms
            .partition_point(|(existing, _)| *existing < mask);
        self.terms.insert(position, (mask, coefficient));
        self
    }

    /// Rebuild an element from raw terms: ascending masks, duplicates summed,
    /// zero coefficients dropped, so the storage invariant holds by
    /// construction after every operation. An overflowing sum cancels its
    /// monomial rather than poisoning the element.
    fn canonical(radicands: Vec<i64>, mut terms: Vec<(usize, Rat)>) -> Self {
        terms.sort_by_key(|(mask, _)| *mask);
        let mut kept: Vec<(usize, Rat)> = Vec::with_capacity(terms.len());
        for (mask, coefficient) in terms {
            if coefficient.is_zero() {
                continue;
            }
            match kept.last_mut() {
                Some((last_mask, last)) if *last_mask == mask => {
                    if let Some(summed) = last.add(coefficient) {
                        *last = summed;
                    } else {
                        kept.pop();
                    }
                }
                _ => kept.push((mask, coefficient)),
            }
        }
        kept.retain(|(_, coefficient)| !coefficient.is_zero());
        Self {
            radicands,
            terms: kept,
        }
    }
    /// Walk a closed expression tree and read it as one field element.
    ///
    /// The structural counterpart of the evaluator's function blind spot:
    /// `5 / sqrt(5)` and its mixed-radical cousins cannot evaluate to a
    /// leaf, but all are exact members of a single multiquadratic field.
    /// `None` when the tree leaves the field: another function (`ln`,
    /// `sin`), a fractional power, more radicands than [`MAX_RADICANDS`], or
    /// any variable.
    pub fn from_tree<T: crate::math::numeric::SymbolicLeaf>(
        node: &crate::math::structs::expr::node::Node<T>,
    ) -> Option<Self> {
        use crate::math::parse::lexer::{Op, Token};
        use crate::math::structs::expr::node::NodeValue;

        let inner = node.inner.borrow();
        match &inner.value {
            NodeValue::Operand(Token::Number(n)) => Some(Self::from_rat(Rat::from_i64(*n))),
            NodeValue::Operand(Token::Rational(value)) => Some(Self::from_rat(*value)),
            NodeValue::Operand(Token::Float(f)) => Rat::from_leaf(f).map(Self::from_rat),
            // `sqrt` of a rational is a field element; `sqrt` of a genuine
            // radical generally leaves the field, so only that case folds.
            NodeValue::Operator(_) if inner.is_sqrt() => {
                let argument = match &inner.value {
                    NodeValue::Operator(op_node) => op_node.right.clone(),
                    _ => return None,
                };
                // The recursion walks freshly cloned subtrees, so the borrow
                // on this node does not need to be released here; the `Ref`
                // guard simply outlives the recursive calls harmlessly.
                let value = Self::from_tree(&argument)?;
                if !value.is_rational() {
                    return None;
                }
                Self::sqrt_rational(value.rational_part())
            }
            NodeValue::Operator(op_node) => {
                let Token::Operator(op) = &op_node.token else {
                    return None;
                };
                let left = Self::from_tree(&op_node.left.clone())?;
                let right = Self::from_tree(&op_node.right.clone())?;
                match op {
                    Op::Add => left.add(&right),
                    Op::Sub => left.sub(&right),
                    Op::Mul | Op::ImplicitMul => left.mul(&right),
                    Op::Div => left.div(&right),
                    // Fractional powers stay symbolic: `2^(1/3)` is not a
                    // quadratic surd and a general one is unreadable.
                    Op::Pow => None,
                }
            }
            _ => None,
        }
    }
}

/// The radical part of the monomial `mask`, fully collected: the product of
/// the selected radicands splits into its squarefree radical times the
/// perfect-square remainder (`sqrt(3) sqrt(15)` is `3 sqrt(5)`). The pair is
/// `(remainder, root)`, the root `None` when the monomial is entirely
/// rational — the remainder then folds into the coefficient.
fn radical_part<T: crate::math::numeric::SymbolicLeaf>(
    radicands: &[i64],
    mask: usize,
) -> Option<(Rat, Option<crate::math::structs::expr::node::Node<T>>)> {
    use crate::math::structs::expr::node::Node;

    let mut product: i128 = 1;
    let mut selected = false;
    for (bit, radicand) in radicands.iter().enumerate() {
        if mask & (1 << bit) != 0 {
            product = product.checked_mul(i128::from(*radicand))?;
            selected = true;
        }
    }
    if !selected {
        return Some((Rat::ONE, None));
    }
    let (squarefree, rest) = surd::squarefree_part(product)?;
    let rest = i64::try_from(rest).ok()?;
    if squarefree <= 1 {
        return Some((Rat::from_i64(rest), None));
    }
    let root = Node::sqrt(Node::number(i64::try_from(squarefree).ok()?));
    Some((Rat::from_i64(rest), Some(root)))
}

/// Merge two radicand lists. Radicands already expressible as subset
/// products of the merged list are absorbed rather than added, keeping the
/// basis independent so every element has one representation.
fn combined_radicands(left: &[i64], right: &[i64]) -> Option<Vec<i64>> {
    let mut radicands: Vec<i64> = Vec::new();
    for candidate in left.iter().chain(right.iter()) {
        if subset_product_matches(&radicands, *candidate) {
            continue;
        }
        if !radicands.contains(candidate) {
            radicands.push(*candidate);
        }
    }
    if radicands.len() > MAX_RADICANDS {
        return None;
    }
    radicands.sort_unstable();
    Some(radicands)
}

/// Whether `candidate`'s squarefree part equals the squarefree part of a
/// nonempty subset product of `radicands`.
fn subset_product_matches(radicands: &[i64], candidate: i64) -> bool {
    if radicands.is_empty() {
        return false;
    }
    let target = match surd::squarefree_part(i128::from(candidate)) {
        Some((squarefree, _)) => squarefree,
        None => return false,
    };
    for mask in 1..(1usize << radicands.len()) {
        let mut product: i128 = 1;
        let mut overflow = false;
        for (bit, radicand) in radicands.iter().enumerate() {
            if mask & (1 << bit) != 0 {
                match product.checked_mul(i128::from(*radicand)) {
                    Some(value) => product = value,
                    None => {
                        overflow = true;
                        break;
                    }
                }
            }
        }
        if overflow {
            continue;
        }
        if let Some((squarefree, _)) = surd::squarefree_part(product)
            && squarefree == target
        {
            return true;
        }
    }
    false
}

/// Express `sqrt(radicand)` in the target basis: the squarefree part maps to
/// the subset of target radicands carrying it, the perfect-square remainder
/// scales the coefficient.
fn decompose_radicand(target: &[i64], radicand: i64) -> Option<(usize, Rat)> {
    let (squarefree, rest) = surd::squarefree_part(i128::from(radicand))?;
    if squarefree == 1 {
        return Some((0, Rat::from_i64(i64::try_from(rest).ok()?)));
    }
    for mask in 1..(1usize << target.len()) {
        let mut product: i128 = 1;
        let mut overflow = false;
        for (bit, value) in target.iter().enumerate() {
            if mask & (1 << bit) != 0 {
                match product.checked_mul(i128::from(*value)) {
                    Some(next) => product = next,
                    None => {
                        overflow = true;
                        break;
                    }
                }
            }
        }
        if overflow {
            continue;
        }
        if let Some((subset_squarefree, subset_rest)) = surd::squarefree_part(product)
            && subset_squarefree == squarefree
        {
            let factor = Rat::from_i64(i64::try_from(rest).ok()?)
                .div(Rat::from_i64(i64::try_from(subset_rest).ok()?))?;
            return Some((mask, factor));
        }
    }
    None
}

impl std::fmt::Display for FieldElement {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // The same rendering the fold prints: collected radicals, signed
        // joins. A zero element renders as the literal zero.
        write!(f, "{}", self.to_node::<crate::math::numeric::Real>())
    }
}
